#include "transpose_maps_arithmetic.hpp"
void ct_equal(CFPoly f,int degree,std::vector<CFPoly>& out){if(f.degree()==degree){out.push_back(f.monic());return;}require(f.degree()>degree&&f.degree()%degree==0,"equal-degree factor block");mpz_class q;mpz_pow_ui(q.get_mpz_t(),prime.get_mpz_t(),unsigned(degree));CFPoly x{Z(0),Z(1)};for(int shift=0;shift<1024;++shift){auto g=cf_gcd(f,powmod(x+CFPoly{Z(shift)},mpz_class((q-1)/2),f)-CFPoly{Z(1)});if(g.degree()>0&&g.degree()<f.degree()){ct_equal(g,degree,out);ct_equal(f.exact(g).monic(),degree,out);return;}}throw std::runtime_error("frozen equal-degree split cap exhausted");}
void ct_factor(CFPoly f,std::vector<CFPoly>& out){f=f.monic();if(f.degree()<1)return;auto repeated=cf_gcd(f,cf_derivative(f));if(repeated.degree()>0){ct_factor(f.exact(repeated),out);ct_factor(repeated,out);return;}CFPoly x{Z(0),Z(1)},power=x;for(int d=1;2*d<=f.degree();++d){power=powmod(power,prime,f);auto block=cf_gcd(f,power-x);if(block.degree()>0){ct_equal(block,d,out);f=f.exact(block).monic();if(f.degree()==0)break;power=power%f;}}if(f.degree()>0)out.push_back(f);}
void ct_irreducible(const CFPoly& f){int d=f.degree();CFPoly x{Z(0),Z(1)},power=x%f;for(int k=1;k<=d;++k){power=powmod(power,prime,f);if(k<d&&d%k==0)require(cf_gcd(f,power-x).degree()==0,"closed-target factor irreducibility");}require(power==x%f,"closed-target factor Frobenius closure");}
struct CTFiber {P u,v;G reduced,trace;CFPoly factor,trace_u,trace_v;};
CTFiber ct_fiber(const MMap& map,const F& tx,const F& ty){
    auto embed=[](const CFPoly& p){return tr_embed(p);};std::array<P,4> eq;for(int k=0;k<2;++k){F power(1);for(auto& row:map.global.at(k?"V":"U").arr){auto scale=embed(map.den.exact(pc_read_poly(row.at("c"))));eq[size_t(2*k)]=eq[size_t(2*k)]+(embed(pc_read_poly(row.at("a")))*scale).scale(power);eq[size_t(2*k+1)]=eq[size_t(2*k+1)]+(embed(pc_read_poly(row.at("b")))*scale).scale(power);power=power*tx;}}eq[2]=eq[2]-embed(map.den).scale(ty);auto gcd=[](const P& a,const P& b){return std::get<0>(xgcd(a,b));};
    CTFiber out;out.u=gcd(gcd(eq[0]*eq[3]-eq[2]*eq[1],eq[0]*eq[0]-eq[1]*eq[1]*curve),eq[2]*eq[2]-eq[3]*eq[3]*curve);for(;;){auto common=gcd(out.u,embed(map.den));if(common.degree()==0)break;out.u=out.u.exact(common).monic();}require(out.u.degree()>0&&out.u.degree()<=9,"closed-target transpose finite degree");auto[g,s,t]=xgcd(eq[1]%out.u,eq[3]%out.u);auto[gg,ss,tt]=xgcd(g,out.u);require(gg.degree()==0,"closed-target transpose y separation");out.v=(-(s*eq[0]+t*eq[2])*ss)%out.u;require(((out.v*out.v-curve)%out.u).degree()<0,"closed-target source incidence");require(((eq[0]+eq[1]*out.v)%out.u).degree()<0&&((eq[2]+eq[3]*out.v)%out.u).degree()<0,"closed-target graph incidence");P u=out.u,v=out.v;while(u.degree()>3){auto q=(curve-v*v).exact(u).monic();require(q.degree()<u.degree(),"closed-target Cantor reduction");v=(-v)%q;u=q;}out.reduced=G{u,v};out.reduced.check();return out;
}
G ct_frob(const G& g){P u=g.u,v=g.v;for(auto& c:u.c)c=c.power(prime);for(auto& c:v.c)c=c.power(prime);G out{u,v};out.check();return out;}
F ct_eval(const CFPoly& p,const F& z){F r;for(int i=p.degree();i>=0;--i)r=r*z+F(CFPoly{p.at(i)});return r;}
G ct_closed(const MMap& map,const CFPoly& u,const CFPoly& x,const CFPoly& y,std::vector<CTFiber>& witnesses){
    require(cm_curve(map.f,u,x,y).degree()<0,"closed-target input curve equation");std::vector<CFPoly> factors;ct_factor(u,factors);CFPoly replay{Z(1)};for(auto& f:factors){ct_irreducible(f);replay=replay*f;}require(replay==u.monic(),"closed-target factor replay including multiplicities");auto saved=modulus;G total;for(auto& factor:factors){modulus=factor;F z(CFPoly{Z(0),Z(1)}),tx=ct_eval(x,z),ty=ct_eval(y,z);auto w=ct_fiber(map,tx,ty);w.factor=factor;G sum,conjugate=w.reduced;for(int i=0;i<factor.degree();++i){sum=sum.add(conjugate);conjugate=ct_frob(conjugate);}require(conjugate==w.reduced,"closed-target source field conjugate closure");w.trace_u=rational(sum.u);w.trace_v=rational(sum.v);modulus=saved;w.trace=G{tr_embed(w.trace_u),tr_embed(w.trace_v)};w.trace.check();total=total.add(w.trace);witnesses.push_back(w);std::cerr<<"closed factor degree="<<factor.degree()<<" raw fiber="<<w.u.degree()<<" traced source degree="<<w.trace_u.degree()<<'\n';}modulus=saved;return total;
}
void ct_emit_poly(const P& p){std::cout<<'[';for(size_t i=0;i<p.c.size();++i){if(i)std::cout<<',';cf_emit_poly(p.c[i].a);}std::cout<<']';}
void ct_emit(const CTFiber& w){std::cout<<"{\"factor\":";cf_emit_poly(w.factor);std::cout<<",\"raw_U\":";ct_emit_poly(w.u);std::cout<<",\"raw_V\":";ct_emit_poly(w.v);std::cout<<",\"trace_U\":";cf_emit_poly(w.trace_u);std::cout<<",\"trace_V\":";cf_emit_poly(w.trace_v);std::cout<<'}';}
int main(int argc,char** argv){try{
    require(argc==5,"usage: closed_transpose study global bridge formal");std::string root=argv[1];initialize_cover(read_json(root+"/inputs/p192-d7-prym.json"));Level2Input input;auto global=read_json(argv[2]),bridge=read_json(argv[3]),formal=read_json(argv[4]),model=read_json(root+"/evidence/p192-d7-kernel3-plane-quartic.json"),points=read_json(root+"/evidence/destination-relations-v2/result.json");EBPoly f;for(auto& row:model.at("terms").arr){auto e=row.at("exponents");f.add({e.arr[0].integer(),e.arr[1].integer()},Z(mpz_class(row.at("coefficient").scalar)));}MMap map(global,f);G reference;for(auto& id:formal.at("seed_indices").arr){auto& p=points.at("points").arr[size_t(id.integer())];reference=reference.add(tr_fiber(map,Z(mpz_class(p.at("x").scalar)),Z(mpz_class(p.at("y").scalar))).reduced);}std::vector<G> answers;std::vector<std::vector<CTFiber>> witnesses;int changed=0;
    for(auto& row:bridge.at("images").arr){auto u=pc_read_poly(row.at("target_U")),y=pc_read_poly(row.at("target_V"));std::vector<CTFiber> w;G value=ct_closed(map,u,CFPoly{Z(0),Z(1)},y,w);G source=cm_source(row);value=value.add(reference.times(source.u.degree()).neg());require(value==source.times(3),"closed-target psi phi exact composition3");require(!(value.add(source)==source.times(3)),"changed closed-target source composition");rejects([&]{require(cm_curve(f,u,CFPoly{Z(0),Z(1)},y+CFPoly{Z(1)}).degree()<0,"changed closed target y");},"changed closed target y");++changed;answers.push_back(value);witnesses.push_back(w);std::cerr<<"source-side composition3 fixture "<<answers.size()-1<<" passed\n";}
    require(G{}.times(3)==G{},"zero source composition");std::cout<<"{\"scope\":\"P192-kernel3-closed-target-transpose\",\"standing\":\"producer-unverified\",\"source_side_composition3_checks\":"<<answers.size()<<",\"zero_checked\":true,\"changed_input_controls\":"<<changed<<",\"reference\":";tr_emit_g(reference);std::cout<<",\"fixtures\":[";for(size_t i=0;i<answers.size();++i){if(i)std::cout<<',';std::cout<<"{\"index\":"<<i<<",\"source_result\":";tr_emit_g(answers[i]);std::cout<<",\"closed_factors\":[";for(size_t j=0;j<witnesses[i].size();++j){if(j)std::cout<<',';ct_emit(witnesses[i][j]);}std::cout<<"]}";}std::cout<<"],\"projective_target_interface_complete\":false}\n";
}catch(const std::exception& e){std::cerr<<"REJECT "<<e.what()<<'\n';return 1;}}
